'use strict';
// Read-only audit of the immutable remote preview. This captures product UI
// observations; independent numerical expectations are recorded separately.
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),assert=require('node:assert/strict'),{chromium}=require('playwright');
const out=path.resolve('docs/qa-fixtures-20261011/preview');fs.mkdirSync(out,{recursive:true});
const commit='c33e9f02e30559cee9ab3c4727785a30f59f5baa',url=`https://raw.githack.com/tgkfnfnfv9-stack/Training-tools/${commit}/index.html`,expectedSha256='812d4d706652b11ce88801f93b2e88370e28b9d4f002417db1d9ecf94302456e';
const report={url,commit,expectedSha256,environment:'Real Linux Chromium, desktop 1280x1000 and touch-emulated 390x844. Immutable commit preview; not GitHub Pages production.',tls:'TLS verification enabled; inherited environment proxy and configured CA trust. No ignoreHTTPSErrors or certificate bypass flags.',checks:{},errors:[],observations:[]};
report.environmentCA={source:'/usr/local/share/ca-certificates/environment-proxy-ca.crt',sha256Fingerprint:'C7:1B:4D:1E:9D:77:75:C5:38:C6:88:AB:10:CE:A9:CE:41:7D:73:12:E8:98:38:F9:D1:5F:F7:32:56:CD:7F:C3',setup:'Initial Chromium TLS error traced to missing configured environment root in existing NSS DB; imported the existing environment CA as OpenAI-environment-proxy, with certificate verification retained.'};
const summarize=rows=>(rows||[]).map(r=>({key:r.key,valid:r.valid,rawUm:r.microns,reason:r.reason||null}));
function write(){fs.writeFileSync(path.join(out,'results.json'),JSON.stringify(report,null,2)+'\n');}
(async()=>{let browser;try{
 const proxyURL=process.env.HTTPS_PROXY||process.env.HTTP_PROXY,proxy=proxyURL?new URL(proxyURL):null;
 browser=await chromium.launch({executablePath:'/usr/bin/chromium',args:['--no-sandbox'],...(proxy?{proxy:{server:proxy.origin,...(proxy.username?{username:decodeURIComponent(proxy.username),password:decodeURIComponent(proxy.password)}:{})}}:{})});
 report.browser=browser.version();const page=await browser.newPage({viewport:{width:1280,height:1000},hasTouch:true,reducedMotion:'reduce'});page.setDefaultTimeout(25000);page.on('pageerror',e=>report.errors.push(e.message));
 let response=await page.goto(url,{waitUntil:'networkidle',timeout:60000});report.externalContentNotice=(await page.title()).includes('External Content Notice');
 if(report.externalContentNotice){await page.screenshot({path:path.join(out,'external-notice.png')});const navigation=page.waitForNavigation({waitUntil:'networkidle',timeout:60000});await page.getByText('Open the page',{exact:true}).click();response=await navigation;}
 report.finalUrl=page.url();report.httpStatus=response.status();report.contentType=response.headers()['content-type'];report.sha256=crypto.createHash('sha256').update(await response.body()).digest('hex');assert.equal(report.httpStatus,200);assert.equal(report.sha256,expectedSha256);report.checks.exactRemoteHTML=true;
 async function read(){return page.evaluate(()=>{const d=JSON.parse($('fixtureComparison').dataset.comparison),row=e=>({key:e.dataset.fixtureMeasurement,values:Object.fromEntries([...e.querySelectorAll('[data-reading]')].map(v=>[v.dataset.reading,{raw:v.dataset.raw,integer:v.querySelector('strong')?.textContent,detail:v.querySelector('small')?.textContent}]))});return {record:levelRecord(),holding:$('fixtureComparison').dataset.holding==='true',status:$('fixtureComparisonStatus').textContent,setupStatus:$('fixtureSetupStatus').textContent,comparison:d,DOM:[...$('fixtureComparisonRows').children].map(row),overflow:document.documentElement.scrollWidth>innerWidth};});}
 async function setup(kind){await page.evaluate(kind=>{openMachine(machines.find(m=>m.kind===kind));stopMotion();machineProfile=MachineAccuracy.generate('used',123456,machineLinearKeys(),supports.length);machineReference=null;machineSavedBest=null;supportHeights=supports.map(()=>0);positions={X:0,Y:0,Z:0,A:0,C:0};updateAxisValues();updateLeveling(false);},kind);}
 async function snapshot(kind,name){const raw=await read(),observation={kind,name,record:raw.record,holding:raw.holding,status:raw.status,setupStatus:raw.setupStatus,initial:summarize(raw.comparison.initial),held:summarize(raw.comparison.held),remounted:summarize(raw.comparison.fresh),DOM:raw.DOM,overflow:raw.overflow};report.observations.push(observation);return observation;}
 for(const [kind,selection,width,height] of [['horizontal','YZ',1280,1000],['lathe','bore',390,844]]){
  await page.setViewportSize({width,height});await setup(kind);const initialAxes=await page.evaluate(()=>({...positions}));
  await page.locator('#fixtureSelection').selectOption(selection);await page.locator('#fixturePosition').click();const stationAxes=await page.evaluate(()=>({...positions}));assert.notDeepEqual(stationAxes,initialAxes);report.checks[kind+'RealStationButtonMovedAxes']=true;
  if(!await page.locator('#fixtureComparison').evaluate(e=>e.open))await page.locator('#fixtureComparison > summary').click();await page.locator('#fixtureCapture').click();const before=await snapshot(kind,'before-support');assert.equal(before.holding,true);assert.ok(before.initial.some(r=>r.valid));
  await page.locator('#supportMap .map-point').nth(1).click();await page.locator('#coarseAdjust').click();await page.locator('#raiseSupport').click();const after=await snapshot(kind,'B-plus-0.010');assert.equal(after.holding,true);assert.ok(after.record.heights.every((v,i)=>v===(i===1?.01:0)));assert.deepEqual(after.record.axisPositions,before.record.axisPositions);assert.equal(after.record.machineProfile.seed,123456);assert.equal(after.overflow,false);
  const changed=after.held.filter(r=>{const fresh=after.remounted.find(q=>q.key===r.key);return r.valid&&fresh?.valid&&Math.abs(r.rawUm-fresh.rawUm)>1e-7;});assert.ok(changed.length>0);report.checks[kind+'RealSupportButtonAndHeldDifference']=changed.map(r=>r.key);
  const target=kind==='horizontal'?'square.YZ':'bore.a',value=after.held.find(r=>r.key===target);assert.equal(value.valid,true);report.checks[kind+'TargetContactValid']=true;
  fs.writeFileSync(path.join(out,kind+'-after.input.json'),JSON.stringify(after.record,null,2)+'\n');await page.screenshot({path:path.join(out,kind+'-B-plus0010-comparison.png')});
  await page.locator('#fixtureGeometryOpen').click();await page.locator('#fixtureProjection').selectOption('oblique');if(kind==='lathe')await page.locator('#fixtureFraming').selectOption('contact');
  const geometry=await page.evaluate(()=>({data:JSON.parse($('fixtureGeometryCanvas').dataset.fixture),status:$('fixtureGeometryStatus').textContent,framing:$('fixtureFraming').value,dialogOpen:$('fixtureGeometryDialog').open,viewport:{width:innerWidth,height:innerHeight},canvasRect:(()=>{const r=$('fixtureGeometryCanvas').getBoundingClientRect();return {x:r.x,y:r.y,width:r.width,height:r.height};})()}));
  assert.equal(geometry.dialogOpen,true);assert.equal(geometry.data.valid,true);assert.ok(geometry.data.contacts.length>0);assert.ok(geometry.canvasRect.width>0&&geometry.canvasRect.height>0);if(kind==='lathe')assert.equal(geometry.framing,'contact');
  fs.writeFileSync(path.join(out,kind+'-fixture-geometry.json'),JSON.stringify(geometry,null,2)+'\n');await page.screenshot({path:path.join(out,kind+(kind==='lathe'?'-mobile-bore-contact':'-desktop-YZ-fixture')+'.png')});report.checks[kind+'ActualFixtureDialogContact']=true;
  await page.locator('#closeFixtureGeometry').click();
 }
 assert.deepEqual(report.errors,[]);report.checks.noBrowserExceptions=true;report.passed=true;
}catch(error){report.passed=false;report.failure=error.stack||String(error);process.exitCode=1;}finally{write();if(browser)await browser.close();console.log(JSON.stringify({url,commit,sha256:report.sha256,httpStatus:report.httpStatus,checks:report.checks,errors:report.errors,passed:report.passed,failure:report.failure?.split('\n').slice(0,5).join('\n')},null,2));}})();
